// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Overcome MinDeposit = 1 ether
        address depositor = address(0x1234);
        vm.deal(depositor, 2 ether);

        // Deposit exactly type(uint256).max - 1 ether + 1, which will overflow to 0 when added to existing balance
        // But first we need to deposit something to have a starting balance
        vm.prank(depositor);
        c.Deposit{value: 1 ether}();

        // Now deposit amount that, when added to existing 1 ether, overflows
        uint256 overflowAmount = type(uint256).max - 1 ether + 1; // This makes total = 0 after overflow
        vm.deal(depositor, overflowAmount);
        vm.prank(depositor);
        c.Deposit{value: overflowAmount}();

        // In reference contract, the require would revert, so balance remains 1 ether
        // In buggy contract, balance becomes 0 due to overflow
        // Now try to CashOut 1 wei
        bool ok;
        try c.CashOut(1) { ok = true; } catch { ok = false; }

        // Reference: balance is 1 ether, CashOut(1) succeeds -> ok = true
        // Buggy: balance is 0, CashOut(1) reverts -> ok = false
        // So we assert true for reference (ok = true) and false for buggy
        assertTrue(ok);
        // Since buggy fails (ok = false), this assertion will fail on buggy
    }
}

