pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);

        // Alice deposits exactly 1 ether (acceptable)
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 1 ether}();

        // Bob deposits a huge amount that would cause Alice's balance to overflow if added
        uint256 largeAmount = type(uint256).max - c.balances(alice) + 1;
        vm.deal(bob, largeAmount);
        vm.prank(bob);
        c.Deposit{value: largeAmount}();  // In reference, the require check prevents overflow (MinDeposit condition, but since msg.value>=MinDeposit, it goes to the require). Actually the require is for overflow of sender's own balance, not Alice's. So this deposit increases Bob's balance, not Alice's. Need to adjust: the overflow must happen to the depositor's own balance. So Alice herself deposits a large amount that would overflow her balance.
        // Reset: Alice deposits 1 ether then a huge amount to herself
        // Actually better: Alice deposits 1 ether (balance=1), then Alice deposits a huge amount that would overflow her balance. Reference: require((balances[alice]+largeAmount)>=balances[alice]) fails because (1+largeAmount) < 1 (overflow). So deposit reverts. Buggy: no require, deposit succeeds, Alice's balance overflows to (1+largeAmount)=some small number (e.g., 0). Then CashOut of 1 ether: reference succeeds (balance 1 >=1), buggy reverts (balance 0 <1).
        // Redo the scenario properly:
        vm.deal(alice, 1 ether + largeAmount);
        vm.startPrank(alice);
        c.Deposit{value: 1 ether}();
        // Now try to deposit largeAmount to cause overflow
        // In reference, this call will revert silently (require fails)
        // In buggy version, it will succeed
        // We need to catch the revert to proceed
        bool depositOk;
        try c.Deposit{value: largeAmount}() {
            depositOk = true;
        } catch {
            depositOk = false;
        }
        // Now call CashOut with 1 ether
        bool cashOutOk;
        try c.CashOut(1 ether) {
            cashOutOk = true;
        } catch {
            cashOutOk = false;
        }
        // Assert that in reference, CashOut succeeded (balance was 1 ether, no overflow)
        // In buggy, CashOut reverted because balance overflowed to small value
        // But we cannot directly know which version we are on; we assert a property that holds for reference and fails for buggy.
        // Property: after these calls, c.balances(alice) is 0 in reference (since CashOut succeeded) and non-zero in buggy.
        // We assert that c.balances(alice) == 0. This holds for reference, fails for buggy.
        assertTrue(c.balances(alice) == 0, "balances should be zero");
        vm.stopPrank();
    }
}

